package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Runs after both claims are saved, so a refused split writes no audit line: the split, naming the
 *  original with its remaining amount, then the new claim's opening. */
public class RecordClaimSplit {
    public void record(@Val ClaimSplit split, @Val Claim claim, People people, ClaimLog log, Audit audit) {
        Claim into = split.into();
        log.write(into, split.user());
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        audit.record("CLAIM_SPLIT sheet=" + claim.getSheetId() + " by=" + split.user()
                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
                + " date=" + claim.getDate() + (claim.getNumber() != null ? " number=" + claim.getNumber() : "")
                + " into=" + into.getNumber());
        audit.record(ClaimAction.OPEN.event() + " sheet=" + into.getSheetId() + " by=" + split.user()
                + " person=" + person.getName() + " amount=" + into.getAmount().toPlainString()
                + " date=" + into.getDate() + " number=" + into.getNumber());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Watches;
import net.officefloor.plugin.variable.Val;

/** Runs after the claim is saved, so a refused status change writes no audit line. */
public class RecordClaimStatusChanged {
    public void record(@Val ClaimStatusChange change, @Val Claim claim, People people, ClaimLog log, Watches watches, Audit audit) {
        log.write(claim, change.user());
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        // A clerk's settle over the clerk limit leaves the claim PENDING: it settles nothing yet.
        boolean pending = change.action() == ClaimAction.SETTLE && claim.getStatus() == ClaimStatus.PENDING;
        boolean fixesDue = !pending && (change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE);
        // Only a claim that was SETTLED has a SETTLED log line, so a void of one reverses its frozen due.
        boolean voidsSettled = change.action() == ClaimAction.VOID && log.settledOn(claim) != null;
        // An open over the review threshold leaves the claim in REVIEW: it is not opened yet.
        boolean review = change.action() == ClaimAction.OPEN && claim.getStatus() == ClaimStatus.REVIEW;
        // A review opens the claim: its own line, then the open's, with its number.
        if (change.action() == ClaimAction.REVIEW) {
            audit.record(change.action().event() + " sheet=" + claim.getSheetId() + " by=" + change.user()
                    + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
                    + " date=" + claim.getDate());
        }
        audit.record((pending ? "CLAIM_PENDING" : review ? "CLAIM_REVIEW" : change.action() == ClaimAction.REVIEW ? ClaimAction.OPEN.event() : change.action().event()) + " sheet=" + claim.getSheetId() + " by=" + change.user()
                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
                + " date=" + claim.getDate() + (claim.getNumber() != null ? " number=" + claim.getNumber() : "")
                + (fixesDue ? " due=" + (claim.getDue() != null ? claim.getDue().toPlainString() : "n/a") : "")
                + (change.action() == ClaimAction.REJECT ? " reason=" + change.reason() : "")
                + (voidsSettled ? " reversed=" + (claim.getDue() != null ? claim.getDue().toPlainString() : "n/a") : "")
                + (change.action() == ClaimAction.VOID && claim.getVoidReason() != null ? " reason=" + claim.getVoidReason() : "")
                + (fixesDue && change.on() != null ? " on=" + change.on() : ""));
        // A watched person's claim settled or approved: a line per watching user, after the claim's own.
        if (fixesDue) watches.notify(claim, person, change.user(), audit);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.holiday.Holidays;
import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.People;
